/** Parse TMDb movie/tv id from AniList externalLinks (site name or URL). */
export function extractTmdbFromExternalLinks(
  links?: Array<{ site?: string; url?: string }> | null,
): { id: number; mediaType: "movie" | "tv" } | null {
  for (const link of links ?? []) {
    const site = (link.site ?? "").toLowerCase().replace(/\s+/g, "");
    const url = link.url ?? "";
    const isTmdb =
      site === "tmdb" ||
      site === "themoviedb" ||
      site === "themoviedatabase" ||
      url.includes("themoviedb.org");
    if (!isTmdb) continue;
    const match = url.match(/themoviedb\.org\/(movie|tv)\/(\d+)/i);
    if (match) {
      const id = Number(match[2]);
      if (Number.isFinite(id) && id > 0) {
        return { id, mediaType: match[1].toLowerCase() as "movie" | "tv" };
      }
    }
  }
  return null;
}

const TITLE_STOP = new Set([
  "the",
  "and",
  "no",
  "of",
  "a",
  "an",
  "to",
  "in",
  "on",
  "wa",
  "wo",
  "ga",
  "ni",
  "de",
  "season",
  "part",
  "movie",
  "film",
  "ova",
  "ona",
  "special",
  "tv",
  "series",
]);

/** Normalize titles for comparison (strip punctuation / season tags). */
export function normalizeTitleKey(s: string): string {
  return s
    .toLowerCase()
    .replace(/[:：].*$/, " ") // drop subtitle after colon for softer series match
    .replace(/\b(season|part|cour|arc)\s*\d+\b/gi, " ")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function significantTokens(s: string): string[] {
  return normalizeTitleKey(s)
    .split(" ")
    .filter((t) => t.length >= 3 && !TITLE_STOP.has(t));
}

/**
 * Jaccard-ish token overlap between two titles (0–1).
 * Rejects loose substring matches that mapped Demon Slayer → unrelated shows.
 */
export function titleTokenSimilarity(a: string, b: string): number {
  const ta = new Set(significantTokens(a));
  const tb = new Set(significantTokens(b));
  if (ta.size === 0 || tb.size === 0) {
    const na = normalizeTitleKey(a);
    const nb = normalizeTitleKey(b);
    if (!na || !nb) return 0;
    if (na === nb) return 1;
    return 0;
  }
  let inter = 0;
  for (const t of ta) if (tb.has(t)) inter += 1;
  return inter / Math.max(ta.size, tb.size);
}

export function titlesLikelySame(
  contentTitle: string,
  candidateName: string,
  alts: string[] = [],
): boolean {
  const candidates = [contentTitle, ...alts].filter(Boolean);
  for (const c of candidates) {
    const sim = titleTokenSimilarity(c, candidateName);
    if (sim >= 0.55) return true;
    const nc = normalizeTitleKey(c);
    const nn = normalizeTitleKey(candidateName);
    if (nc && nn && (nc === nn || nc.includes(nn) || nn.includes(nc))) {
      // Only allow includes when both sides have enough tokens (avoid short junk)
      if (significantTokens(c).length >= 2 && significantTokens(candidateName).length >= 2) {
        return true;
      }
      if (nc === nn) return true;
    }
  }
  return false;
}

type TmdbSearchRow = {
  id?: number;
  title?: string;
  name?: string;
  original_title?: string;
  original_name?: string;
  release_date?: string;
  first_air_date?: string;
  genre_ids?: number[];
  origin_country?: string[];
  original_language?: string;
  popularity?: number;
};

/**
 * Resolve a missing TMDb id for anime/series so Watch Now can open the
 * episode embed player (same path as Attack on Titan).
 *
 * STRICT for anime: Japanese + Animation + high title similarity only.
 * Loose substring matching previously caused wrong streams (e.g. unrelated TV).
 */
export async function resolveTmdbIdForTitle(opts: {
  title: string;
  year?: number | null;
  preferMovie?: boolean;
  alternateTitles?: string[];
  /**
   * When true, only accept TMDB matches that are actually animation (genre 16).
   * Prevents an anime from resolving to its LIVE-ACTION adaptation.
   */
  requireAnimation?: boolean;
}): Promise<{ tmdb: number; tmdbMediaType: "movie" | "tv" } | null> {
  const queries = [
    opts.title,
    ...(opts.alternateTitles ?? []).filter(
      (t) => t && t.toLowerCase() !== opts.title.toLowerCase(),
    ),
  ].filter(Boolean) as string[];

  // Anime series → TV only; anime movies → movie only. Never mix.
  const searchMovie = opts.preferMovie || !opts.requireAnimation;
  const searchTv = !opts.preferMovie || !opts.requireAnimation;

  for (const q of queries.slice(0, 4)) {
    const [movies, tv] = await Promise.all([
      searchMovie
        ? tmdbGet<{ results?: TmdbSearchRow[] }>("/search/movie", { query: q })
        : Promise.resolve({ results: [] as TmdbSearchRow[] }),
      searchTv
        ? tmdbGet<{ results?: TmdbSearchRow[] }>("/search/tv", { query: q })
        : Promise.resolve({ results: [] as TmdbSearchRow[] }),
    ]);

    const scoreHit = (
      r: TmdbSearchRow,
      mediaType: "movie" | "tv",
    ): number => {
      if (!r.id) return -1;
      const names = [r.title, r.name, r.original_title, r.original_name]
        .filter(Boolean)
        .map(String);
      // STRICT: must look like the same title (token overlap), not mere substring
      if (
        !names.some((n) =>
          titlesLikelySame(q, n, [opts.title, ...(opts.alternateTitles ?? [])]),
        )
      ) {
        return -1;
      }
      if (opts.requireAnimation) {
        if (!r.genre_ids?.includes(16)) return -1;
        // Anime almost always ja (or rarely zh/ko for donghua/manhwa adapt)
        const lang = (r.original_language ?? "").toLowerCase();
        if (lang && !["ja", "zh", "ko"].includes(lang)) return -1;
      }

      let score = Math.min(r.popularity ?? 0, 200);
      const bestName =
        names.find((n) => normalizeTitleKey(n) === normalizeTitleKey(q)) ??
        names[0]!;
      const sim = Math.max(
        ...names.map((n) =>
          titleTokenSimilarity(q, n),
        ),
      );
      score += sim * 2000;
      if (normalizeTitleKey(bestName) === normalizeTitleKey(q)) score += 800;
      const date = r.release_date || r.first_air_date || "";
      const year = date ? Number(date.slice(0, 4)) : null;
      if (opts.year && year && Math.abs(year - opts.year) <= 1) score += 400;
      if (r.original_language === "ja") score += 250;
      if (r.genre_ids?.includes(16)) score += 200;
      if (opts.preferMovie && mediaType === "movie") score += 100;
      if (!opts.preferMovie && mediaType === "tv") score += 100;
      return score;
    };

    const candidates: Array<{
      tmdb: number;
      tmdbMediaType: "movie" | "tv";
      score: number;
    }> = [];

    for (const r of movies?.results ?? []) {
      const s = scoreHit(r, "movie");
      if (s >= 0 && r.id) {
        candidates.push({ tmdb: r.id, tmdbMediaType: "movie", score: s });
      }
    }
    for (const r of tv?.results ?? []) {
      const s = scoreHit(r, "tv");
      if (s >= 0 && r.id) {
        candidates.push({ tmdb: r.id, tmdbMediaType: "tv", score: s });
      }
    }

    candidates.sort((a, b) => b.score - a.score);
    // High bar: require strong title similarity (sim*2000 alone needs ~0.55+)
    if (candidates[0] && candidates[0].score >= 1200) {
      return {
        tmdb: candidates[0].tmdb,
        tmdbMediaType: candidates[0].tmdbMediaType,
      };
    }
  }
  return null;
}

/**
 * Verify an existing TMDB id still matches the catalog title.
 * Clears wrong links (Demon Slayer → TallBoyz style mismatches).
 */
/**
 * Verify a TMDB id really is the given title.
 * - "match": the TMDB entry's name matches (id is trustworthy for playback).
 * - "no_match": name does not match (wrong show linked — drop the id).
 * - "match_not_anime": name matches but requireAnimation failed (e.g. an
 *   English cartoon like The Spectacular Spider-Man that AniList lists as
 *   "anime"). The id is still CORRECT and playable — the caller should keep it
 *   and reclassify to a live-action type instead of discarding it.
 */
export type TmdbVerifyResult = "match" | "no_match" | "match_not_anime";

export async function verifyTmdbMatchesTitleDetailed(opts: {
  tmdbId: number;
  mediaType: "movie" | "tv";
  title: string;
  alternateTitles?: string[];
  requireAnimation?: boolean;
}): Promise<TmdbVerifyResult> {
  const path =
    opts.mediaType === "movie"
      ? `/movie/${opts.tmdbId}`
      : `/tv/${opts.tmdbId}`;
  const detail = await tmdbGet<{
    id?: number;
    title?: string;
    name?: string;
    original_title?: string;
    original_name?: string;
    original_language?: string;
    genres?: Array<{ id?: number }>;
  }>(path);
  if (!detail?.id) return "no_match";

  const names = [
    detail.title,
    detail.name,
    detail.original_title,
    detail.original_name,
  ].filter(Boolean) as string[];

  if (
    !names.some((n) =>
      titlesLikelySame(opts.title, n, opts.alternateTitles ?? []),
    )
  ) {
    return "no_match";
  }

  if (opts.requireAnimation) {
    const genreIds = (detail.genres ?? []).map((g) => Number(g.id));
    const lang = (detail.original_language ?? "").toLowerCase();
    // Name matches but it's not Japanese/CJK animation → correct title, wrong
    // bucket. Signal so the caller keeps the id and reclassifies to series.
    if (!genreIds.includes(16)) return "match_not_anime";
    if (lang && !["ja", "zh", "ko"].includes(lang)) return "match_not_anime";
  }
  return "match";
}

/** Back-compat boolean wrapper — true only for a full "match". */
export async function verifyTmdbMatchesTitle(opts: {
  tmdbId: number;
  mediaType: "movie" | "tv";
  title: string;
  alternateTitles?: string[];
  requireAnimation?: boolean;
}): Promise<boolean> {
  return (await verifyTmdbMatchesTitleDetailed(opts)) === "match";
}

function mapAnilist(m: AnilistMedia): Content | null {
  // Adult anime is included when the catalog loads with includeMature
  const title =
    m.title?.english || m.title?.romaji || m.title?.native || null;
  if (!title) return null;
  const cover = m.coverImage?.extraLarge || m.coverImage?.large;
  const format = normalizeAnimeFormat(m.format);
  if (format === "MUSIC" || format === "UNKNOWN") return null;

  let trailer: Trailer | null = null;
  if (m.trailer?.id && m.trailer.site?.toLowerCase() === "youtube") {
    const ytKey = String(m.trailer.id).trim();
    trailer = {
      id: `yt_${ytKey}`,
      key: ytKey,
      site: "youtube",
      name: "Trailer",
      official: true,
      type: "Trailer",
    };
  }

  const statusMap: Record<string, Content["status"]> = {
    RELEASING: "airing",
    FINISHED: "ended",
    NOT_YET_RELEASED: "upcoming",
    CANCELLED: "canceled",
  };

  // Extract TMDb ID from externalLinks (e.g. "https://www.themoviedb.org/tv/1429" → 1429)
  const fromLinks = extractTmdbFromExternalLinks(m.externalLinks);
  const tmdbId = fromLinks?.id;
  let tmdbMediaType = fromLinks?.mediaType;
  // Anime series must always be TV embeds — never movie (Demon Slayer wrong-film bug).
  // Only true AniList MOVIE format uses movie path.
  if (format === "MOVIE") {
    tmdbMediaType = "movie";
  } else if (tmdbId) {
    tmdbMediaType = "tv";
  }

  // Adults-only detection beyond AniList `isAdult` (which flags only hentai):
  // Ecchi / sexual-content genres mark adult-oriented anime (e.g. "Overflow",
  // an R18+ ecchi that AniList does NOT set isAdult on). These must hide when
  // the 18+ toggle is off — hence a distinct `anime-adult-genre` tag.
  const genreLower = (m.genres ?? []).map((g) => g.toLowerCase());
  const adultGenre = genreLower.some(
    (g) => g === "hentai" || g === "ecchi" || g === "erotica",
  );

  const animeSlug = slugify(`${title}-${m.id}`) || `anilist-${m.id}`;
  return safeParse({
    id: `anilist_${m.id}`,
    slug: animeSlug === "title" ? `anilist-${m.id}` : animeSlug,
    contentType: "anime",
    title,
    englishTitle: m.title?.english,
    romajiTitle: m.title?.romaji,
    nativeTitle: m.title?.native,
    originalTitle: m.title?.native,
    alternateTitles: [m.title?.english, m.title?.romaji, m.title?.native].filter(
      Boolean,
    ) as string[],
    overview: (m.description ?? "")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<[^>]+>/g, ""),
    poster: cover
      ? { url: cover, source: "anilist" }
      : { url: posterFallback(title, 0x7867ff), source: "local" },
    backdrop: m.bannerImage
      ? { url: m.bannerImage, source: "anilist" }
      : null,
    releaseDate: m.startDate?.year ? `${m.startDate.year}-01-01` : null,
    year: m.startDate?.year ?? null,
    status: statusMap[m.status ?? ""] ?? "unknown",
    language: "ja",
    countries: ["JP"],
    genres: (m.genres ?? []).map((g) => ({ id: slugify(g), name: g })),
    runtime: m.duration ?? null,
    seasonCount: null,
    episodeCount: m.episodes ?? null,
    ageRating: m.isAdult ? "18+" : adultGenre ? "R+" : null,
    scores: m.averageScore
      ? [{ source: "anilist", score: m.averageScore / 10 }]
      : [],
    popularity: m.popularity ?? 0,
    trailer,
    watchProviders: [],
    providerIds: {
      anilist: m.id,
      ...(m.idMal ? { mal: m.idMal } : {}),
      ...(tmdbId ? { tmdb: tmdbId, tmdbMediaType } : {}),
    },
    animeFormat: format,
    studios: (m.studios?.nodes ?? [])
      .map((n) => n.name)
      .filter(Boolean) as string[],
    // AniList isAdult = hentai (ground truth). Adult-oriented ecchi genres are
    // tagged separately so the 18+ OFF gate hides them without treating them as
    // explicit sexual content in the curated 18+ library.
    tags: m.isAdult
      ? ["18+", "mature", "adult-anime", "anilist-adult", "anime", "explicit"]
      : adultGenre
        ? ["r+", "mature", "adults-only", "anime-adult-genre", "anime"]
        : format === "MOVIE"
          ? ["anime", "anime-movie", "film"]
          : ["anime"],
    nextEpisodeAt: m.nextAiringEpisode?.airingAt
      ? new Date(m.nextAiringEpisode.airingAt * 1000).toISOString()
      : null,
    approved: true,
    mature: Boolean(m.isAdult) || adultGenre,
    lastSyncedAt: new Date().toISOString(),
  });
}

export function mapAnilistCredits(m: AnilistMedia, contentId: string): {
  cast: Credit[];
  crew: Credit[];
} {
  const cast: Credit[] = [];
  const crew: Credit[] = [];
  let order = 0;
  for (const edge of m.characters?.edges ?? []) {
    const node = edge.node;
    if (!node?.name?.full) continue;
    const charIdx = order;
    cast.push({
      id: `${contentId}_char_${node.id ?? "x"}_${charIdx}`,
      contentId,
      personId: `anilist_char_${node.id ?? charIdx}`,
      personName: node.name.full,
      profilePath: node.image?.large || node.image?.medium || null,
      character: edge.role ?? "Character",
      job: null,
      department: "Acting",
      order: order++,
      creditType: "cast",
    });
    const va = edge.voiceActors?.[0];
    if (va?.name?.full) {
      const vaIdx = order;
      cast.push({
        id: `${contentId}_va_${va.id ?? "x"}_${node.id ?? "c"}_${vaIdx}`,
        contentId,
        personId: `anilist_va_${va.id ?? vaIdx}`,
        personName: va.name.full,
        profilePath: va.image?.large || va.image?.medium || null,
        character: `VA · ${node.name.full}`,
        job: "Voice Actor",
        department: "Acting",
        order: order++,
        creditType: "cast",
      });
    }
  }
  let crewOrder = 0;
  for (const edge of m.staff?.edges ?? []) {
    const node = edge.node;
    if (!node?.name?.full) continue;
    const roleSlug = (edge.role ?? "staff").replace(/\W+/g, "_").slice(0, 40);
    // Same person can appear multiple times with different roles — index + role must be unique
    crew.push({
      id: `${contentId}_staff_${node.id ?? "x"}_${roleSlug}_${crewOrder}`,
      contentId,
      personId: `anilist_staff_${node.id ?? crewOrder}`,
      personName: node.name.full,
      profilePath: node.image?.large || node.image?.medium || null,
      character: null,
      job: edge.role ?? "Staff",
      department: "Crew",
      order: crewOrder++,
      creditType: "crew",
    });
  }
  return { cast, crew };
}

export type WorldCatalogPage = {
  items: Content[];
  page: number;
  totalPages: number;
  total: number;
};

export async function fetchAnilistAnime(opts?: {
  page?: number;
  search?: string;
  sort?: string;
  status?: string;
  perPage?: number;
  seasonYear?: number;
  /** When true, request 18+ anime catalog from AniList */
  isAdult?: boolean;
  format?: string;
}): Promise<Content[]> {
  const page = await fetchAnilistAnimePage(opts);
  return page.items;
}

/** Paginated anime browse — AniList holds essentially the full anime catalog */
export async function fetchAnilistAnimePage(opts?: {
  page?: number;
  search?: string;
  sort?: string;
  status?: string;
  perPage?: number;
  seasonYear?: number;
  isAdult?: boolean;
  /** AniList MediaFormat: TV, MOVIE, OVA, ONA, SPECIAL, … */
  format?: string;
}): Promise<WorldCatalogPage> {
  const page = Math.max(1, opts?.page ?? 1);
  const perPage = Math.min(50, Math.max(1, opts?.perPage ?? 50));
  // AniList: isAdult true = adult only, false = safe only.
  // Omit the field entirely when undefined — never send null (can empty results).
  const variables: Record<string, unknown> = {
    page,
    perPage,
    sort: [opts?.sort ?? "POPULARITY_DESC"],
  };
  if (opts?.search) variables.search = opts.search;
  if (opts?.status) variables.status = opts.status;
  if (opts?.seasonYear) variables.seasonYear = opts.seasonYear;
  if (opts?.format) variables.format = opts.format;
  if (opts?.isAdult !== undefined) variables.isAdult = Boolean(opts.isAdult);
  else variables.isAdult = false; // default safe catalog

  const data = await fetchJson<{
    data?: {
      Page?: {
        pageInfo?: {
          total?: number;
          currentPage?: number;
          lastPage?: number;
          hasNextPage?: boolean;
        };
        media?: AnilistMedia[];
      };
    };
  }>(ANILIST, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify({
      query: ANIME_QUERY,
      variables,
    }),
  });
  const pageInfo = data?.data?.Page?.pageInfo;
  const items = (data?.data?.Page?.media ?? [])
    .map(mapAnilist)
    .filter(Boolean) as Content[];
  const total = pageInfo?.total ?? items.length;
  const lastPage = pageInfo?.lastPage ?? Math.max(1, Math.ceil(total / perPage));
  return {
    items,
    page: pageInfo?.currentPage ?? page,
    totalPages: Math.max(1, lastPage),
    total,
  };
}

export async function fetchAnilistById(id: number): Promise<{
  content: Content | null;
  cast: Credit[];
  crew: Credit[];
  trailers: Trailer[];
}> {
  const data = await fetchJson<{
    data?: { Page?: { media?: AnilistMedia[] } };
  }>(ANILIST, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify({
      query: ANIME_QUERY,
      variables: { page: 1, perPage: 1, search: undefined, sort: ["POPULARITY_DESC"] },
    }),
  });
  // Better: Media(id: $id) query
  const detail = await fetchJson<{
    data?: { Media?: AnilistMedia };
  }>(ANILIST, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify({
      query: `
        query ($id: Int) {
          Media(id: $id, type: ANIME, isAdult: false) {
            id format status episodes duration averageScore popularity description genres isAdult
            title { romaji english native }
            coverImage { large extraLarge }
            bannerImage startDate { year }
            trailer { id site }
            studios { nodes { name } }
            nextAiringEpisode { airingAt }
            idMal
            externalLinks { site url }
            characters(sort: [ROLE, RELEVANCE, FAVOURITES_DESC], perPage: 16) {
              edges {
                role
                node { id name { full } image { large medium } }
                voiceActors(language: JAPANESE, sort: [RELEVANCE, ID]) {
                  id name { full } image { large medium }
                }
              }
            }
            staff(sort: [RELEVANCE, ID], perPage: 12) {
              edges { role node { id name { full } image { large medium } } }
            }
          }
        }
      `,
      variables: { id },
    }),
  });
  void data;
  const media = detail?.data?.Media;
  if (!media) return { content: null, cast: [], crew: [], trailers: [] };
  const content = mapAnilist(media);
  if (!content) return { content: null, cast: [], crew: [], trailers: [] };
  const credits = mapAnilistCredits(media, content.id);
  const trailers = content.trailer ? [content.trailer] : [];
  return { content, ...credits, trailers };
}

export async function fetchAllAnimeLive(
  includeMature = false,
): Promise<Content[]> {
  const year = new Date().getFullYear();
  // Deep popularity/trending pages for cache warm; full catalog is on-demand paginated
  const popularPages = await Promise.all(
    Array.from({ length: 12 }, (_, i) =>
