/**
 * Popular movies for a specific origin country (Korean / Japanese / Chinese /
 * Thai / Filipino …). Feeds the homepage "Popular {country} movies" rows and
 * warms the country movie catalog. Tagged popular so todayOnly() surfaces them.
 */
export async function fetchTmdbMoviesByCountry(
  country: string,
  includeMature = false,
): Promise<Content[]> {
  const cc = country.toUpperCase();
  const adult = includeMature ? "true" : "false";
  // PH: also pull Tagalog-original titles that sometimes miss origin_country
  const phLangPages =
    cc === "PH"
      ? tmdbFetchManyPages(
          "/discover/movie",
          {
            with_original_language: "tl",
            sort_by: "popularity.desc",
            include_adult: adult,
            language: "en-US",
          },
          4,
        )
      : Promise.resolve([] as Record<string, unknown>[]);

  const [popular, top, recent, phLang] = await Promise.all([
    tmdbFetchManyPages(
      "/discover/movie",
      {
        with_origin_country: cc,
        sort_by: "popularity.desc",
        include_adult: adult,
        language: "en-US",
      },
      8,
    ),
    tmdbFetchManyPages(
      "/discover/movie",
      {
        with_origin_country: cc,
        sort_by: "vote_average.desc",
        "vote_count.gte": "20",
        include_adult: adult,
        language: "en-US",
      },
      4,
    ),
    tmdbFetchManyPages(
      "/discover/movie",
      {
        with_origin_country: cc,
        sort_by: "primary_release_date.desc",
        "primary_release_date.lte": new Date().toISOString().slice(0, 10),
        "vote_count.gte": "5",
        include_adult: adult,
        language: "en-US",
      },
      4,
    ),
    phLangPages,
  ]);
  return [...popular, ...top, ...recent, ...phLang]
    .map((r) => mapTmdbMovie(r, cc))
    .map((c) =>
      c
        ? {
            ...c,
            tags: Array.from(
              new Set([...(c.tags ?? []), "trending-today", "popular"]),
            ),
          }
        : c,
    )
    .filter(Boolean) as Content[];
}

